<?php
/** TEMP PS S1632 run v — V: patikra po apply (sumos DB vs eksportas; imtis; partijos; kadras prekės kortelei). READ-ONLY. */
add_action('init', function(){
  if (!isset($_GET['ps_s1632v'])) return;
  $f=(string)$_GET['ps_s1632v'];
  $o=array('v'=>'S1632 v'); global $wpdb; $p=$wpdb->prefix;
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $sk=$wpdb->get_results("SELECT pm.meta_value sku, pm.post_id, po.post_type, po.post_status FROM {$p}postmeta pm JOIN {$p}posts po ON po.ID=pm.post_id AND po.post_type IN('product','product_variation') WHERE pm.meta_key='_sku' AND pm.meta_value<>''");
  $map=array(); foreach($sk as $r){ $map[trim((string)$r->sku)]=array((int)$r->post_id,$r->post_type,$r->post_status); }
  $lauk=0; $yra=0; $blogi=array(); $tikrinta=0; $agg=array();
  foreach(array_filter(explode("\n",gzdecode(base64_decode('')))) as $l){ $c=explode(';',$l); $s=trim($c[0]); $q=(int)$c[2];
    if(strpos($s,'gift-coupon')===0 || preg_match('/-dp\d*$/i',$s)) continue;
    $hit=$map[$s] ?? ('PET'===substr($s,0,3)?($map[substr($s,3)]??null):null);
    if(!$hit||$hit[2]!=='publish'||$hit[1]!=='product') continue;
    $pid=$hit[0]; $agg[$pid]=array(($agg[$pid][0]??0)+$q,$s);
  }
  foreach($agg as $pid=>$a){ list($q,$s)=$a;
    $pr=wc_get_product($pid); if(!$pr||$pr->is_type('variable')) continue;
    $tiek=get_post_meta($pid,'_vf_qty',true)!==''||get_post_meta($pid,'_zb_qty',true)!=='';
    $db=(int)get_post_meta($pid,$tiek?'_own_stock_qty':'_stock',true);
    $tikrinta++; $lauk+=$q; $yra+=$db;
    if($db!==$q && count($blogi)<12) $blogi[]=$s.' #'.$pid.' lauk'.$q.' db'.$db.($tiek?' own':'');
  }
  $o['paprastos']=array('tikrinta'=>$tikrinta,'lauk_suma'=>$lauk,'db_suma'=>$yra,'nesutampa_pvz'=>$blogi);
  $vl=0;$vy=0;$vb=array();$vt=0;
  $norm=function($s){ $s=mb_strtolower(trim($s)); return str_replace(array('ė','ž','š','ų','ū','į','ą','č',' '),array('e','z','s','u','u','i','a','c',''),$s); };
  foreach(array_filter(explode("\n",gzdecode(base64_decode('')))) as $l){ $c=explode(';',$l); list($bs,$at,$re,$vk,$q)=array(trim($c[0]),$c[1],trim($c[2]),trim($c[3]),(int)$c[4]);
    if(strpos($bs,'gift')===0) continue; $vid=0;
    if(isset($map[$bs])){ $pr=wc_get_product($map[$bs][0]);
      if($pr && $pr->is_type('variable')){ foreach($pr->get_children() as $cid){ $v=wc_get_product($cid); if(!$v)continue;
        foreach($v->get_attributes() as $tax=>$slug){ $t=get_term_by('slug',$slug,$tax); if($norm($t?$t->name:$slug)===$norm($re)){ $vid=$cid; break 2; } } } } }
    if(!$vid && $vk!=='' && isset($map[$vk]) && $map[$vk][1]==='product_variation') $vid=$map[$vk][0];
    if(!$vid) continue;
    $db=(int)get_post_meta($vid,'_stock',true); $vt++; $vl+=$q; $vy+=$db;
    if($db!==$q && count($vb)<12) $vb[]=$bs.'/'.$re.' #'.$vid.' lauk'.$q.' db'.$db;
  }
  $o['variacijos']=array('tikrinta'=>$vt,'lauk_suma'=>$vl,'db_suma'=>$vy,'nesutampa_pvz'=>$vb);
  $o['partiju_s1632']=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$p}ps_partijos WHERE pastaba LIKE 'Pradinis likutis (testas S1632)%'");
  $o['partiju_kiekis_suma']=(int)$wpdb->get_var("SELECT COALESCE(SUM(kiekis_liko),0) FROM {$p}ps_partijos WHERE pastaba LIKE 'Pradinis likutis (testas S1632)%'");
  $o['ping']=wp_remote_retrieve_response_code(wp_remote_get(home_url('/'),array('timeout'=>30,'sslverify'=>false)));
  // kadrai: viena partija turinti preke + varianto puslapis parduotuveje
  $pv=$wpdb->get_row("SELECT product_id FROM {$p}ps_partijos WHERE pastaba LIKE 'Pradinis likutis (testas S1632)%' ORDER BY id ASC LIMIT 1");
  $tu=get_user_by('login','testuotojas'); $uid=$tu->ID; $exp=time()+1200; $tok=WP_Session_Tokens::get_instance($uid)->create($exp); $li=wp_generate_auth_cookie($uid,$exp,'logged_in',$tok);
  $o['cookies']=array(array('name'=>LOGGED_IN_COOKIE,'value'=>$li));
  $o['shots']=array(
    array('n'=>'s1632_v_partija_kortele','u'=>admin_url('post.php?post='.(int)$pv->product_id.'&action=edit'),'w'=>1440,'h'=>1100),
    array('n'=>'s1632_v_variacija_front','u'=>get_permalink(wp_get_post_parent_id(34300)?:34300),'w'=>1280,'h'=>1000)
  );
  header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE); exit;
},99);
